class Dispatcher:
    def __init__(self, bot):
        self.bot = bot
        self.handlers = []

    def message(self, *filters):
        def decorator(func):
            self.handlers.append({"func": func, "filters": filters})
            return func

        return decorator

    def process(self, message):
        for handler in self.handlers:
            func = handler["func"]
            filters = handler["filters"]

            is_match = True
            for f in filters:
                if callable(f) and not hasattr(f, "check"):
                    if not f(message):
                        is_match = False
                        break
                elif hasattr(f, "check"):
                    if not f.check(message):
                        is_match = False
                        break
                else:
                    is_match = False
                    break

            if is_match:
                func(message)
                return
